test_patch:
diff --git a/mysql-test/r/grant_dynamic.result b/mysql-test/r/grant_dynamic.result
index 0385c1f55cd6..dd865eea189f 100644
--- a/mysql-test/r/grant_dynamic.result
+++ b/mysql-test/r/grant_dynamic.result
@@ -769,3 +769,15 @@ DROP USER u1;
 DROP USER u2;
 DROP USER u3;
 # End of test for WL#7194
+# REVOKE ALL IS NOT REVOKING ALL PRIVILEGE WHEN CURRENT_USER() IS USED
+CREATE USER u1@localhost IDENTIFIED BY 'foo';
+GRANT ALL ON *.* TO u1@localhost;
+SHOW GRANTS;
+Grants for u1@localhost
+GRANT SELECT, INSERT, UPDATE, DELETE, CREATE, DROP, RELOAD, SHUTDOWN, PROCESS, FILE, REFERENCES, INDEX, ALTER, SHOW DATABASES, SUPER, CREATE TEMPORARY TABLES, LOCK TABLES, EXECUTE, REPLICATION SLAVE, REPLICATION CLIENT, CREATE VIEW, SHOW VIEW, CREATE ROUTINE, ALTER ROUTINE, CREATE USER, EVENT, TRIGGER, CREATE TABLESPACE, CREATE ROLE, DROP ROLE ON *.* TO `u1`@`localhost`
+GRANT BACKUP_ADMIN,BINLOG_ADMIN,CONNECTION_ADMIN,ENCRYPTION_KEY_ADMIN,GROUP_REPLICATION_ADMIN,PERSIST_RO_VARIABLES_ADMIN,REPLICATION_SLAVE_ADMIN,RESOURCE_GROUP_ADMIN,RESOURCE_GROUP_USER,ROLE_ADMIN,SET_USER_ID,SYSTEM_VARIABLES_ADMIN,XA_RECOVER_ADMIN ON *.* TO `u1`@`localhost`
+REVOKE ALL ON *.* FROM CURRENT_USER();
+SHOW GRANTS;
+Grants for u1@localhost
+GRANT USAGE ON *.* TO `u1`@`localhost`
+DROP USER u1@localhost;
diff --git a/mysql-test/t/grant_dynamic.test b/mysql-test/t/grant_dynamic.test
index f96097ea793b..498c96641904 100644
--- a/mysql-test/t/grant_dynamic.test
+++ b/mysql-test/t/grant_dynamic.test
@@ -520,5 +520,17 @@ GRANT XA_RECOVER_ADMIN ON *.* TO u3;
 DROP USER u1;
 DROP USER u2;
 DROP USER u3;
-
 --echo # End of test for WL#7194
+
+--echo # REVOKE ALL IS NOT REVOKING ALL PRIVILEGE WHEN CURRENT_USER() IS USED
+CREATE USER u1@localhost IDENTIFIED BY 'foo';
+GRANT ALL ON *.* TO u1@localhost;
+connect (con2,localhost,u1,foo,,);
+connection con2;
+SHOW GRANTS;
+REVOKE ALL ON *.* FROM CURRENT_USER();
+SHOW GRANTS;
+connection default;
+disconnect con2;
+DROP USER u1@localhost;
+
